import 'package:flutter/material.dart';import '../../core/app_state.dart';import '../../core/models.dart';enum CaptureType{task,want,future,goal,inbox}Future<void>showQuickCapture(BuildContext c)async{final s=AppStateScope.of(c);await showModalBottomSheet<void>(context:c,isScrollControlled:true,showDragHandle:true,builder:(_)=>_Sheet(state:s));}class _Sheet extends StatefulWidget{const _Sheet({required this.state});final AppState state;@override State<_Sheet>createState()=>_SheetState();}class _SheetState extends State<_Sheet>{final c=TextEditingController();CaptureType type=CaptureType.inbox;@override void dispose(){c.dispose();super.dispose();}void save(){final x=c.text.trim();if(x.isEmpty)return;switch(type){case CaptureType.task:widget.state.addTask(x,bucket:TaskBucket.soon);case CaptureType.want:widget.state.addWant(x);case CaptureType.future:widget.state.addFuture(x);case CaptureType.goal:widget.state.addGoal(x);case CaptureType.inbox:widget.state.addInbox(x);}Navigator.pop(context);}@override Widget build(BuildContext x)=>Padding(padding:EdgeInsets.fromLTRB(20,4,20,MediaQuery.viewInsetsOf(x).bottom+20),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('何か覚えておく？',style:Theme.of(x).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),TextField(controller:c,autofocus:true,maxLines:3,minLines:1,decoration:const InputDecoration(hintText:'例：冬に温泉旅行したい')),const SizedBox(height:12),Wrap(spacing:8,runSpacing:8,children:[('Inbox',Icons.inbox_outlined,CaptureType.inbox),('やること',Icons.check_box_outlined,CaptureType.task),('買いたい',Icons.shopping_bag_outlined,CaptureType.want),('予定候補',Icons.push_pin_outlined,CaptureType.future),('目標',Icons.flag_outlined,CaptureType.goal)].map((e)=>ChoiceChip(label:Row(mainAxisSize:MainAxisSize.min,children:[Icon(e.$2,size:17),const SizedBox(width:5),Text(e.$1)]),selected:type==e.$3,onSelected:(_)=>setState(()=>type=e.$3))).toList()),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:save,child:const Text('保存')))]));}